<?php if($role==='customer'): ?><p><a class="button" href="<?= site_url('bookings/new') ?>">Request a service</a></p><?php endif ?>
<section class="panel"><h2><?= $role==='technician'?'Assigned jobs':'Bookings and service history' ?></h2><?php if(!$bookings): ?><p>No bookings to show.</p><?php else: ?><div class="table-wrap"><table><thead><tr><th>Booking</th><th>Service</th><th>Status</th><th>Preferred time</th><th>Confirmed time</th></tr></thead><tbody><?php foreach($bookings as $b): ?><tr><td><a href="<?= site_url('bookings/'.$b['id']) ?>">#<?= (int)$b['id'] ?></a></td><td><?= esc($b['service_name']) ?></td><td><span class="badge"><?= esc($b['status']) ?></span></td><td><?= esc($b['preferred_at']) ?></td><td><?= esc($b['scheduled_at']??'Awaiting review') ?></td></tr><?php endforeach ?></tbody></table></div><?php endif ?></section>
